//! Raw declarations for `include/ugds.h` and a runtime loader.
//!
//! Nothing is linked at build time. [`UgdsApi`] resolves every function from
//! `libugds.so` when it is created; a symbol missing from the loaded library is
//! reported through that function's `Result` field, so callers can detect newer
//! APIs before calling them. The generated `UgdsApi::uGDS*` methods panic when
//! their symbol is missing.
//!
//! All functions are `unsafe` and follow the C contracts documented in `ugds.h`.
//! The declarations are generated by `regen.sh`; do not edit `src/bindings.rs`.

pub use libloading;

#[rustfmt::skip]
#[allow(non_camel_case_types, non_snake_case, non_upper_case_globals, clippy::all)]
mod bindings;
pub use bindings::*;

/// The shared library produced by the CMake `ugds` target.
pub const LIBRARY_NAME: &str = "libugds.so";

impl UgdsApi {
    /// Loads [`LIBRARY_NAME`] through the platform dynamic-loader search path.
    ///
    /// # Safety
    ///
    /// Loading runs the library's initialization routines; see
    /// [`libloading::Library::new`].
    pub unsafe fn load_default() -> Result<Self, libloading::Error> {
        Self::new(LIBRARY_NAME)
    }
}
